// Cloudflare Worker entry: the Next.js app built by OpenNext, plus the
// hourly cron trigger that calls the daily price-list sync route (it
// syncs only on the first call after 17:00 Sofia time).
// @ts-ignore: generated by `opennextjs-cloudflare build` (missing before the first build)
import { default as handler } from "./.open-next/worker.js";

type Env = { CRON_SECRET?: string };

export default {
  fetch: handler.fetch,

  async scheduled(_controller: unknown, env: Env, ctx: { waitUntil(p: Promise<unknown>): void }) {
    const req = new Request("https://cron.internal/api/cron/price-sync", {
      headers: { authorization: `Bearer ${env.CRON_SECRET ?? ""}` },
    });
    ctx.waitUntil(
      handler.fetch(req, env, ctx).then(async (res: Response) => console.log(`[nutrikal] price-sync cron: ${res.status} ${await res.text()}`)),
    );
  },
};
